typedef unsigned long long big_int;

class string_buf
{
  big_int *data;
  int ref_count;
public:
  int char_length;
};

class stringx
{
  char *chars;
  string_buf *my_buf;
public:
  inline const char operator[](int i) const
  {
    if (i < 0)
      i += my_buf->char_length;
    return chars[i];
  }
  inline int size() const
  {
    return my_buf->char_length;
  }
};

struct char_info
{
  int x0;
  int y0;
  int x1;
  int y1;
  int adv;
};

class typeface_def
{
  char_info char_infos[256];
public:
  const char_info *get_char_info(int c) const
  {
    return &char_infos[c];
  }
  int text_height(const stringx &s) const;
};

int typeface_def::text_height( const stringx &s ) const
{
  int largest_h = 0;
  const char_info *ci;
  int ssize = s.size();

  for (int i = 0; i<ssize; ++i)
  {
    if( s[i] == '\\' )
    {
      ++i;
      if (i>=ssize-1) break;
      if( s[i] == 'n' ) break;
      if( s[i] == 'c' ) { i += 9; }
      continue;
    }
    ci = get_char_info(s[i]);
    if(ci)
    {
      int h = ci->y1 - ci->y0 + 1;
      if ( h > largest_h )
      {
        largest_h = h;
      }
    }
  }
  return largest_h;
}
